package com.gameaggregator.featureflagservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="feature_flags") public class FeatureFlag{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String flagKey;@Column(nullable=false)public String description;@Column(nullable=false)public boolean enabled;@Column(nullable=false)public boolean killSwitch;@Column(nullable=false)public int rolloutPercentage;@Lob @Column(nullable=false)public String clientTargetsJson="[]";@Column(nullable=false)public Instant createdAt=Instant.now();@Version public long revision;protected FeatureFlag(){}public FeatureFlag(String k,String d,boolean e,int p,String c){flagKey=k;description=d;enabled=e;rolloutPercentage=p;clientTargetsJson=c;}}